CREATE OR REPLACE FUNCTION public.add_credits(p_user_id uuid, p_credits integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_credits = -1 THEN
    UPDATE user_credits SET is_unlimited = true, updated_at = now()
    WHERE user_id = p_user_id;
  ELSE
    INSERT INTO user_credits (user_id, credits) VALUES (p_user_id, p_credits)
    ON CONFLICT (user_id) DO UPDATE
    SET credits = user_credits.credits + p_credits, updated_at = now();
  END IF;
END;
$function$
;
ALTER FUNCTION public.add_credits(p_user_id uuid, p_credits integer) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.admin_db_size_breakdown()
 RETURNS TABLE(table_name text, size_bytes bigint, row_estimate bigint)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select
    c.relname::text,
    pg_total_relation_size(c.oid)::bigint,
    c.reltuples::bigint
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind = 'r'
  order by pg_total_relation_size(c.oid) desc;
$function$
;
ALTER FUNCTION public.admin_db_size_breakdown() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.admin_db_total_size()
 RETURNS bigint
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select pg_database_size(current_database())::bigint;
$function$
;
ALTER FUNCTION public.admin_db_total_size() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.admin_top_tenants_by_rows()
 RETURNS TABLE(owner_id uuid, business_name text, email text, total_rows bigint)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with sums as (
    select owner_id, count(*)::bigint as n from public.bookings where owner_id is not null group by owner_id
    union all
    select owner_id, count(*) from public.leads where owner_id is not null group by owner_id
    union all
    select owner_id, count(*) from public.email_logs where owner_id is not null group by owner_id
    union all
    select business_id as owner_id, count(*) from public.messages where business_id is not null group by business_id
    union all
    select owner_id, count(*) from public.anamnese where owner_id is not null group by owner_id
    union all
    select owner_id, count(*) from public.prescriptions where owner_id is not null group by owner_id
    union all
    select owner_id, count(*) from public.invoices where owner_id is not null group by owner_id
  ), agg as (
    select owner_id, sum(n)::bigint as total_rows from sums group by owner_id
  )
  select a.owner_id, p.business_name, p.email, a.total_rows
  from agg a
  left join public.profiles p on p.id = a.owner_id
  order by a.total_rows desc
  limit 20;
$function$
;
ALTER FUNCTION public.admin_top_tenants_by_rows() OWNER TO postgres;

