CREATE OR REPLACE FUNCTION public.business_lookup_for_inbound(p_whatsapp_phone_number_id text)
 RETURNS TABLE(business_id uuid, business_name text, sector text, city text, language text, is_active boolean, cal_api_key text, cal_username text, whatsapp_access_token text, whatsapp_waba_id text, working_hours jsonb, faq jsonb, message_templates jsonb, system_prompt text, services jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    p.id,
    p.business_name,
    p.sector,
    p.city,
    p.language,
    p.is_active,
    (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE id = p.cal_api_key_secret_id),
    p.cal_username,
    (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE id = p.whatsapp_access_token_secret_id),
    p.whatsapp_waba_id,
    p.working_hours,
    p.faq,
    p.message_templates,
    p.system_prompt,
    COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
        'id', s.id,
        'name', s.name,
        'description', s.description,
        'duration_minutes', s.duration_minutes,
        'price_eur', s.price_eur,
        'cal_event_type_id', s.cal_event_type_id,
        'follow_up_days', s.follow_up_days
      ) ORDER BY s.display_order)
       FROM public.business_services s
       WHERE s.business_id = p.id AND s.is_active = TRUE),
      '[]'::jsonb
    )
  FROM public.profiles p
  WHERE p.whatsapp_phone_number_id = p_whatsapp_phone_number_id
    AND p.is_active = TRUE
  LIMIT 1;
END;
$function$
;
ALTER FUNCTION public.business_lookup_for_inbound(p_whatsapp_phone_number_id text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.business_lookup_for_twilio(p_to_number text)
 RETURNS TABLE(business_id uuid, business_name text, sector text, city text, language text, is_active boolean, cal_api_key text, cal_username text, whatsapp_number text, whatsapp_access_token text, whatsapp_waba_id text, working_hours jsonb, faq jsonb, message_templates jsonb, system_prompt text, services jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
DECLARE
  v_clean_number TEXT;
BEGIN
  v_clean_number := REPLACE(REPLACE(REPLACE(p_to_number, 'whatsapp:', ''), ' ', ''), '-', '');

  RETURN QUERY
  SELECT
    p.id,
    p.business_name,
    p.sector,
    p.city,
    p.language,
    p.is_active,
    (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE id = p.cal_api_key_secret_id),
    p.cal_username,
    p.whatsapp_number,
    (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE id = p.whatsapp_access_token_secret_id),
    p.whatsapp_waba_id,
    p.working_hours,
    p.faq,
    p.message_templates,
    p.system_prompt,
    COALESCE(
      (SELECT jsonb_agg(jsonb_build_object(
        'id', s.id,
        'name', s.name,
        'description', s.description,
        'duration_minutes', s.duration_minutes,
        'price_eur', s.price_eur,
        'cal_event_type_id', s.cal_event_type_id,
        'follow_up_days', s.follow_up_days
      ) ORDER BY s.display_order)
       FROM public.business_services s
       WHERE s.business_id = p.id AND s.is_active = TRUE),
      '[]'::jsonb
    )
  FROM public.profiles p
  WHERE p.whatsapp_number = v_clean_number
    AND p.is_active = TRUE
  LIMIT 1;
END;
$function$
;
ALTER FUNCTION public.business_lookup_for_twilio(p_to_number text) OWNER TO postgres;

