CREATE OR REPLACE FUNCTION public.find_patient_by_name_and_birth(p_vorname text, p_nachname text, p_geburtsdatum date, p_owner_id uuid)
 RETURNS TABLE(id uuid, first_name text, last_name text, geburtsdatum date, phone text, email text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT 
    l.id, l.first_name, l.last_name,
    (l.metadata->>'geburtsdatum')::DATE AS geburtsdatum,
    l.phone, l.email
  FROM leads l
  WHERE 
    l.owner_id = p_owner_id
    AND (
      (LOWER(l.first_name) = LOWER(p_vorname) AND LOWER(l.last_name) = LOWER(p_nachname))
      OR
      (LOWER(l.first_name) LIKE LOWER('%' || p_vorname || '%') 
       AND LOWER(l.last_name) LIKE LOWER('%' || p_nachname || '%'))
    )
    AND (
      p_geburtsdatum IS NULL 
      OR (l.metadata->>'geburtsdatum')::DATE = p_geburtsdatum
    )
  LIMIT 5;
END;
$function$
;
ALTER FUNCTION public.find_patient_by_name_and_birth(p_vorname text, p_nachname text, p_geburtsdatum date, p_owner_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.fn_abrechnung_uebermittlung_festschreibung()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'Ein Eintrag der Uebermittlungsdokumentation kann nicht geloescht werden (Anlage 1 TP5 Kap. 3(2): mindestens 2 Jahre Aufbewahrungspflicht).';
  end if;

  if new.id                       is distinct from old.id
  or new.richtung                 is distinct from old.richtung
  or new.physikalischer_dateiname is distinct from old.physikalischer_dateiname
  or new.erstellt_am              is distinct from old.erstellt_am
  or new.laufende_nummer          is distinct from old.laufende_nummer
  or new.transfernummer           is distinct from old.transfernummer
  or new.partner_ik               is distinct from old.partner_ik
  or new.absender_ik              is distinct from old.absender_ik
  or new.begonnen_am              is distinct from old.begonnen_am
  or new.dateigroesse_bytes       is distinct from old.dateigroesse_bytes
  or new.sha256                   is distinct from old.sha256
  or new.betriebsart              is distinct from old.betriebsart
  or new.owner_id                 is distinct from old.owner_id
  or new.abrechnung_id            is distinct from old.abrechnung_id
  or new.created_at               is distinct from old.created_at
  then
    raise exception 'Uebermittlungsdokumentation ist festgeschrieben (Anlage 1 TP5 Kap. 3(2)). Gesperrte Stammdaten duerfen nicht geaendert werden.';
  end if;

  if old.beendet_am is not null and new.beendet_am is distinct from old.beendet_am then
    raise exception 'beendet_am darf nur einmalig ergaenzt werden (NULL -> Wert) und danach nicht mehr veraendert werden.';
  end if;

  if old.antwort_auf is not null and new.antwort_auf is distinct from old.antwort_auf then
    raise exception 'antwort_auf darf nur einmalig ergaenzt werden (NULL -> Wert) und danach nicht mehr veraendert werden.';
  end if;

  if old.uebertragungsweg is not null and new.uebertragungsweg is distinct from old.uebertragungsweg then
    raise exception 'uebertragungsweg darf nur einmalig ergaenzt werden (NULL -> Wert) und danach nicht mehr veraendert werden.';
  end if;

  return new;
end $function$
;
ALTER FUNCTION public.fn_abrechnung_uebermittlung_festschreibung() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.fn_abrechnung_zahlung_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_soll numeric; v_abg numeric; v_bez numeric;
begin
  select coalesce(sum(netto_eur),0), coalesce(sum(absetzung_eur),0)
    into v_soll, v_abg from public.abrechnung_zeile where abrechnung_id = new.abrechnung_id;
  if v_soll = 0 then
    select coalesce(total_eur,0) - coalesce(zuzahlung_total,0)
      into v_soll from public.abrechnung where id = new.abrechnung_id;
    v_abg := 0;
  end if;
  select coalesce(sum(betrag_eur),0)
    into v_bez from public.abrechnung_zahlung where abrechnung_id = new.abrechnung_id;

  if v_bez >= (v_soll - v_abg) - 0.005 then
    update public.abrechnung
       set status = 'paid', paid_at = new.datum::timestamptz
     where id = new.abrechnung_id and status <> 'paid';
  elsif v_bez < (v_soll - v_abg) - 0.005 then
    update public.abrechnung
       set status = 'accepted', paid_at = null
     where id = new.abrechnung_id and status = 'paid';
  end if;
  return new;
end $function$
;
ALTER FUNCTION public.fn_abrechnung_zahlung_status() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.fn_abrechnung_zeile_festschreibung()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'Eine eingereichte Abrechnungszeile kann nicht geloescht werden (GoBD, §302 SGB V). Korrektur: neue Einreichung (VKZ 04).';
  end if;

  if new.owner_id                is distinct from old.owner_id
  or new.business_id             is distinct from old.business_id
  or new.created_at              is distinct from old.created_at
  or new.abrechnung_id           is distinct from old.abrechnung_id
  or new.prescription_id        is distinct from old.prescription_id
  or new.kostentraeger_ik       is distinct from old.kostentraeger_ik
  or new.karten_ik              is distinct from old.karten_ik
  or new.einzel_rechnungsnummer is distinct from old.einzel_rechnungsnummer
  or new.belegnummer            is distinct from old.belegnummer
  or new.verordnungsdatum       is distinct from old.verordnungsdatum
  or new.heilmittel_position    is distinct from old.heilmittel_position
  or new.anzahl_einheiten       is distinct from old.anzahl_einheiten
  or new.leistungen             is distinct from old.leistungen
  or new.brutto_eur             is distinct from old.brutto_eur
  or new.zuzahlung_eur          is distinct from old.zuzahlung_eur
  or new.netto_eur              is distinct from old.netto_eur
  or new.herkunft               is distinct from old.herkunft
  then
    raise exception 'Eingereichte Abrechnungszeile ist festgeschrieben (GoBD). Offen bleiben nur status, absetzung_* und die Anonymisierung.';
  end if;

  if new.patient_name is not null and new.patient_name is distinct from old.patient_name then
    raise exception 'patient_name darf nur auf NULL gesetzt werden (Anonymisierung).';
  end if;
  if new.versichertennummer is not null and new.versichertennummer is distinct from old.versichertennummer then
    raise exception 'versichertennummer darf nur auf NULL gesetzt werden (Anonymisierung).';
  end if;

  new.updated_at := timezone('utc', now());
  return new;
end $function$
;
ALTER FUNCTION public.fn_abrechnung_zeile_festschreibung() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.fn_befreiung_backfill_prescriptions()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_patient_id UUID;
BEGIN
  v_patient_id := COALESCE(NEW.patient_id, OLD.patient_id);
  IF v_patient_id IS NULL THEN
    RETURN NULL;
  END IF;
  UPDATE prescriptions
  SET zuzahlung_befreit = fn_is_patient_befreit(
    patient_id,
    COALESCE(ausstellungsdatum, CURRENT_DATE)
  )
  WHERE patient_id = v_patient_id
    AND abrechnung_id IS NULL;
  RETURN NULL;
END;
$function$
;
ALTER FUNCTION public.fn_befreiung_backfill_prescriptions() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.fn_check_booking_closed_day()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_closed_days INTEGER[];
  v_dow INTEGER;
BEGIN
  IF NEW.business_id IS NULL THEN RETURN NEW; END IF;
  SELECT closed_days INTO v_closed_days FROM public.businesses WHERE id = NEW.business_id;
  IF v_closed_days IS NULL OR array_length(v_closed_days, 1) IS NULL THEN
    RETURN NEW;
  END IF;
  -- Berlin saatine göre gün hesapla
  v_dow := EXTRACT(DOW FROM (NEW.start_time AT TIME ZONE 'Europe/Berlin'))::INTEGER;
  IF v_dow = ANY (v_closed_days) THEN
    RAISE EXCEPTION 'Geschäft ist an diesem Tag geschlossen (closed_days check)' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $function$
;
ALTER FUNCTION public.fn_check_booking_closed_day() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.fn_is_patient_befreit(p_patient_id uuid, p_datum date)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM zuzahlung_befreiung
    WHERE patient_id = p_patient_id
      AND befreit_ab <= p_datum
      AND (befreit_bis IS NULL OR befreit_bis >= p_datum)
  );
$function$
;
ALTER FUNCTION public.fn_is_patient_befreit(p_patient_id uuid, p_datum date) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.fn_patient_consents_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.consented_at > (now() - interval '10 years') THEN
      RAISE EXCEPTION
        'Einwilligung ist nach §630f Abs. 3 BGB 10 Jahre aufzubewahren (unterschrieben am %).',
        OLD.consented_at::date
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;

  -- UPDATE: nur Widerrufsfelder duerfen sich aendern.
  IF NEW.id                  IS DISTINCT FROM OLD.id
     OR NEW.owner_id         IS DISTINCT FROM OLD.owner_id
     OR NEW.patient_id       IS DISTINCT FROM OLD.patient_id
     OR NEW.consent_type     IS DISTINCT FROM OLD.consent_type
     OR NEW.text_version     IS DISTINCT FROM OLD.text_version
     OR NEW.text_sha256      IS DISTINCT FROM OLD.text_sha256
     OR NEW.text_snapshot    IS DISTINCT FROM OLD.text_snapshot
     OR NEW.signature_path   IS DISTINCT FROM OLD.signature_path
     OR NEW.signed_name      IS DISTINCT FROM OLD.signed_name
     OR NEW.consented_at     IS DISTINCT FROM OLD.consented_at
     OR NEW.captured_by_user_id IS DISTINCT FROM OLD.captured_by_user_id
     OR NEW.device_label     IS DISTINCT FROM OLD.device_label
  THEN
    RAISE EXCEPTION
      'Einwilligungsnachweis ist unveraenderlich (Art. 7 Abs. 1 DSGVO). Nur revoked_at/revoke_reason duerfen gesetzt werden.'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$
;
ALTER FUNCTION public.fn_patient_consents_immutable() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.fn_prescriptions_set_befreit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.patient_id IS NULL THEN
    RETURN NEW;
  END IF;
  NEW.zuzahlung_befreit := fn_is_patient_befreit(
    NEW.patient_id,
    COALESCE(NEW.ausstellungsdatum, CURRENT_DATE)
  );
  RETURN NEW;
END;
$function$
;
ALTER FUNCTION public.fn_prescriptions_set_befreit() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.fn_zuzahlung_guthaben_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IN ('ausgezahlt', 'verfallen') THEN
    NEW.updated_at := timezone('utc', now());
    RETURN NEW;
  END IF;
  NEW.status := CASE
    WHEN NEW.rest_eur = 0                 THEN 'verrechnet'
    WHEN NEW.rest_eur < NEW.betrag_eur    THEN 'teilweise_verrechnet'
    ELSE 'offen'
  END;
  NEW.updated_at := timezone('utc', now());
  RETURN NEW;
END;
$function$
;
ALTER FUNCTION public.fn_zuzahlung_guthaben_status() OWNER TO postgres;

