CREATE OR REPLACE FUNCTION public.mitarbeiter_zuordnen(p_owner uuid, p_mitarbeiter uuid, p_limit integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  n integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('mitarbeiter_' || p_owner::text));

  SELECT count(*) INTO n
    FROM public.profiles
   WHERE owner_id = p_owner
     AND role = 'employee'
     AND is_active IS NOT FALSE
     AND id <> p_mitarbeiter;

  IF p_limit IS NOT NULL AND n >= p_limit THEN
    RAISE EXCEPTION 'PLAN_LIMIT' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.profiles
     SET owner_id = p_owner, role = 'employee'
   WHERE id = p_mitarbeiter
     AND owner_id IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'MITARBEITER_NICHT_ZUORDENBAR' USING ERRCODE = 'P0001';
  END IF;
END;
$function$
;
ALTER FUNCTION public.mitarbeiter_zuordnen(p_owner uuid, p_mitarbeiter uuid, p_limit integer) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.naechste_datenaustauschreferenz(p_owner uuid, p_absender_ik text, p_empfaenger_ik text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_n bigint;
begin
  if p_owner is null or btrim(coalesce(p_absender_ik,'')) = '' or btrim(coalesce(p_empfaenger_ik,'')) = '' then
    raise exception 'naechste_datenaustauschreferenz: owner, Absender-IK und Empfaenger-IK sind Pflicht';
  end if;

  insert into datenaustausch_zaehler (absender_ik, empfaenger_ik, owner_id, letzte_referenz)
  values (p_absender_ik, p_empfaenger_ik, p_owner, 1)
  on conflict (absender_ik, empfaenger_ik) do update
    set letzte_referenz = datenaustausch_zaehler.letzte_referenz + 1,
        owner_id = coalesce(datenaustausch_zaehler.owner_id, excluded.owner_id),
        aktualisiert_am = now()
  returning letzte_referenz into v_n;

  return ((v_n - 1) % 99999)::integer + 1;
end $function$
;
ALTER FUNCTION public.naechste_datenaustauschreferenz(p_owner uuid, p_absender_ik text, p_empfaenger_ik text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.naechste_nummer(p_owner uuid, p_kreis text, p_jahr integer)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_nr bigint;
BEGIN
  INSERT INTO nummernkreise (owner_id, kreis, jahr, last_nr)
       VALUES (p_owner, p_kreis, p_jahr, 1)
  ON CONFLICT (owner_id, kreis, jahr)
  DO UPDATE SET last_nr = nummernkreise.last_nr + 1
  RETURNING last_nr INTO v_nr;
  RETURN v_nr;
END;
$function$
;
ALTER FUNCTION public.naechste_nummer(p_owner uuid, p_kreis text, p_jahr integer) OWNER TO postgres;
COMMENT ON FUNCTION public.naechste_nummer(p_owner uuid, p_kreis text, p_jahr integer) IS 'Atomare Nummernvergabe je Inhaber/Kreis/Jahr. ON CONFLICT DO UPDATE sperrt die Zeile, zwei gleichzeitige Aufrufe bekommen verschiedene Nummern.';

CREATE OR REPLACE FUNCTION public.naechste_transfernummer(p_owner uuid, p_absender_ik text, p_empfaenger_ik text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_n integer;
begin
  if p_owner is null or btrim(coalesce(p_absender_ik,'')) = '' or btrim(coalesce(p_empfaenger_ik,'')) = '' then
    raise exception 'naechste_transfernummer: owner, Absender-IK und Empfaenger-IK sind Pflicht';
  end if;

  insert into datenaustausch_zaehler (absender_ik, empfaenger_ik, owner_id, letzte_transfernummer)
  values (p_absender_ik, p_empfaenger_ik, p_owner, 1)
  on conflict (absender_ik, empfaenger_ik) do update
    set letzte_transfernummer = (datenaustausch_zaehler.letzte_transfernummer + 1) % 1000,
        owner_id = coalesce(datenaustausch_zaehler.owner_id, excluded.owner_id),
        aktualisiert_am = now()
  returning letzte_transfernummer into v_n;

  return v_n;
end $function$
;
ALTER FUNCTION public.naechste_transfernummer(p_owner uuid, p_absender_ik text, p_empfaenger_ik text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.naechste_verordnungsnummer(p_owner uuid, p_lead uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('vo_nr_' || p_owner::text || '_' || p_lead::text));

  -- Seit der Zusammenlegung der Verordnungstoepfe (04.09.2026) gibt es nur
  -- noch EINE Tabelle. Vorher: UNION ALL ueber prescriptions + verordnungen.
  SELECT COALESCE(MAX(verordnungsnummer), 0) + 1 INTO n
    FROM prescriptions
   WHERE owner_id = p_owner AND patient_id = p_lead;

  RETURN n;
END;
$function$
;
ALTER FUNCTION public.naechste_verordnungsnummer(p_owner uuid, p_lead uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.normalize_phone(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  cleaned text;
begin
  if p is null then return null; end if;
  cleaned := regexp_replace(p, '[^0-9+]', '', 'g');
  if cleaned like '+%' then return cleaned; end if;
  if cleaned like '00%' then return '+' || substring(cleaned from 3); end if;
  if cleaned like '0%' then return '+49' || substring(cleaned from 2); end if;
  if length(cleaned) = 11 and cleaned like '49%' then return '+' || cleaned; end if;
  if length(cleaned) >= 10 then return '+' || cleaned; end if;
  return cleaned;
end;
$function$
;
ALTER FUNCTION public.normalize_phone(p text) OWNER TO postgres;

