CREATE OR REPLACE FUNCTION public.pat_fussbefund_versionieren()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_max integer;
BEGIN
  -- Spalten-DEFAULTs laufen vor BEFORE-ROW-Triggern, NEW.id ist also gefuellt.
  NEW.eintrag_id := coalesce(NEW.eintrag_id, NEW.id);
  NEW.serie_id   := coalesce(NEW.serie_id,   NEW.id);

  SELECT max(version) INTO v_max
    FROM public.pat_fussbefund
   WHERE eintrag_id = NEW.eintrag_id;

  NEW.version := coalesce(v_max, 0) + 1;

  IF v_max IS NOT NULL THEN
    UPDATE public.pat_fussbefund
       SET ist_aktuell = false
     WHERE eintrag_id = NEW.eintrag_id
       AND ist_aktuell;
  END IF;

  NEW.ist_aktuell := true;

  -- Selbstheilung: eine fortgesetzte Serie behaelt ihre Farbe, auch wenn der
  -- Client sie nicht mitgeschickt hat.
  IF NEW.serie_farbe IS NULL THEN
    SELECT serie_farbe INTO NEW.serie_farbe
      FROM public.pat_fussbefund
     WHERE serie_id = NEW.serie_id AND serie_farbe IS NOT NULL
     LIMIT 1;
  END IF;

  RETURN NEW;
END;
$function$
;
ALTER FUNCTION public.pat_fussbefund_versionieren() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.pending_signup_consume(p_pending_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault', 'pg_catalog'
AS $function$
DECLARE
  v_secret_id uuid;
  v_pw text;
BEGIN
  SELECT password_secret_id INTO v_secret_id FROM public.pending_signups WHERE id = p_pending_id;
  IF v_secret_id IS NULL THEN RETURN NULL; END IF;
  SELECT decrypted_secret INTO v_pw FROM vault.decrypted_secrets WHERE id = v_secret_id;
  RETURN v_pw;
END;
$function$
;
ALTER FUNCTION public.pending_signup_consume(p_pending_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.pending_signup_delete(p_pending_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault', 'pg_catalog'
AS $function$
DECLARE
  v_secret_id uuid;
BEGIN
  SELECT password_secret_id INTO v_secret_id FROM public.pending_signups WHERE id = p_pending_id;
  IF v_secret_id IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_secret_id;
  END IF;
  DELETE FROM public.pending_signups WHERE id = p_pending_id;
END;
$function$
;
ALTER FUNCTION public.pending_signup_delete(p_pending_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.pending_signup_store(p_email text, p_onboarding jsonb, p_password text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault', 'pg_catalog'
AS $function$
DECLARE
  v_old RECORD;
  v_secret_id uuid;
  v_id uuid;
BEGIN
  FOR v_old IN SELECT id, password_secret_id FROM public.pending_signups WHERE email = p_email LOOP
    IF v_old.password_secret_id IS NOT NULL THEN
      DELETE FROM vault.secrets WHERE id = v_old.password_secret_id;
    END IF;
  END LOOP;
  DELETE FROM public.pending_signups WHERE email = p_email;

  v_secret_id := vault.create_secret(
    p_password,
    'pending_pw:' || p_email || ':' || gen_random_uuid()::text,
    'Temporary signup password (pre-payment)'
  );

  INSERT INTO public.pending_signups (email, onboarding_data, password_secret_id)
  VALUES (p_email, p_onboarding, v_secret_id)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$
;
ALTER FUNCTION public.pending_signup_store(p_email text, p_onboarding jsonb, p_password text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.podologie_behandlungen_festschreibung()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.behandlungsdatum  is distinct from old.behandlungsdatum
  or new.hpnr_codes        is distinct from old.hpnr_codes
  or new.diagnosegruppe    is distinct from old.diagnosegruppe
  or new.lokalisation      is distinct from old.lokalisation
  or new.notizen           is distinct from old.notizen
  or new.betrag_gkv        is distinct from old.betrag_gkv
  or new.owner_id          is distinct from old.owner_id
  or new.created_at        is distinct from old.created_at
  then
    raise exception 'Dokumentierte Behandlung ist unveraenderlich (§ 630f Abs. 1 S. 2 BGB). Eine Korrektur erfolgt durch Stornierung mit Grund und eine neue Behandlungszeile.';
  end if;

  if old.storniert_am is not null
     and (new.storniert_am  is distinct from old.storniert_am
       or new.storno_grund  is distinct from old.storno_grund
       or new.storniert_von is distinct from old.storniert_von)
  then
    raise exception 'Eine Stornierung laesst sich nicht zuruecknehmen oder aendern (§ 630f Abs. 1 S. 2 BGB).';
  end if;

  if new.verordnung_id is not null
     and new.verordnung_id is distinct from old.verordnung_id
  then
    raise exception 'Die Zuordnung zur Verordnung ist festgeschrieben und kann nur aufgehoben (NULL), nicht umgehaengt werden.';
  end if;

  if old.employee_id is not null
     and new.employee_id is not null
     and new.employee_id is distinct from old.employee_id
  then
    raise exception 'Die durchfuehrende Person ist festgeschrieben und kann nicht ausgetauscht werden.';
  end if;

  return new;
end $function$
;
ALTER FUNCTION public.podologie_behandlungen_festschreibung() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.podologie_behandlungen_kein_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  raise exception 'Eine dokumentierte Behandlung kann nicht geloescht werden (§ 630f Abs. 1 S. 2 BGB). Bitte stornieren — die Zeile bleibt sichtbar, zaehlt aber nicht mehr.';
end $function$
;
ALTER FUNCTION public.podologie_behandlungen_kein_delete() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.podologie_empfangsnachweis_append(p_owner_id uuid, p_pruefer_id uuid, p_behandlung_id uuid, p_status text, p_therapeuteninitialen text DEFAULT NULL::text, p_dokument_id bigint DEFAULT NULL::bigint, p_grund text DEFAULT NULL::text)
 RETURNS podologie_empfangsnachweise
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    v_behandlung public.podologie_behandlungen%ROWTYPE;
    v_prev public.podologie_empfangsnachweise%ROWTYPE;
    v_initialen text;
    v_grund text;
    v_dokument_id bigint;
    v_vorgaenger_id uuid := NULL;
    v_now timestamptz;
    v_result public.podologie_empfangsnachweise%ROWTYPE;
BEGIN
    -- Actor verification: caller must supply matching owner and pruefer UUID
    IF p_owner_id IS NULL OR p_pruefer_id IS NULL THEN
        RAISE EXCEPTION 'Owner ID and Pruefer ID must not be null'
            USING ERRCODE = '42501';
    END IF;

    IF p_owner_id IS DISTINCT FROM p_pruefer_id THEN
        RAISE EXCEPTION 'Owner ID and Pruefer ID must match'
            USING ERRCODE = '42501';
    END IF;

    -- Profile must be owner role without an upstream owner_id
    IF NOT EXISTS (
        SELECT 1
        FROM public.profiles
        WHERE id = p_owner_id
          AND role = 'owner'
          AND owner_id IS NULL
    ) THEN
        RAISE EXCEPTION 'Pruefer must be an existing owner profile with owner_id IS NULL'
            USING ERRCODE = '42501';
    END IF;

    -- Treatment ID check
    IF p_behandlung_id IS NULL THEN
        RAISE EXCEPTION 'Treatment ID must not be null'
            USING ERRCODE = '23514';
    END IF;

    -- Status validation
    IF p_status IS NULL OR p_status NOT IN ('bestaetigt', 'widerrufen') THEN
        RAISE EXCEPTION 'Invalid status: %, expected bestaetigt or widerrufen', p_status
            USING ERRCODE = '23514';
    END IF;

    -- Parameter shape checks prior to locking
    IF p_status = 'bestaetigt' THEN
        IF p_therapeuteninitialen IS NULL THEN
            RAISE EXCEPTION 'Therapeuteninitialen must not be null for bestaetigt'
                USING ERRCODE = '23514';
        END IF;
        v_initialen := pg_catalog.btrim(p_therapeuteninitialen, E' \t\r\n');
        IF pg_catalog.length(v_initialen) < 1 OR pg_catalog.length(v_initialen) > 16 THEN
            RAISE EXCEPTION 'Therapeuteninitialen must be between 1 and 16 non-blank characters'
                USING ERRCODE = '23514';
        END IF;

        IF p_grund IS NOT NULL THEN
            v_grund := pg_catalog.btrim(p_grund, E' \t\r\n');
            IF pg_catalog.length(v_grund) > 500 THEN
                RAISE EXCEPTION 'Grund must not exceed 500 characters'
                    USING ERRCODE = '23514';
            END IF;
            IF pg_catalog.length(v_grund) = 0 THEN
                v_grund := NULL;
            END IF;
        ELSE
            v_grund := NULL;
        END IF;
    ELSIF p_status = 'widerrufen' THEN
        IF p_grund IS NULL THEN
            RAISE EXCEPTION 'Grund must not be null for widerrufen'
                USING ERRCODE = '23514';
        END IF;
        v_grund := pg_catalog.btrim(p_grund, E' \t\r\n');
        IF pg_catalog.length(v_grund) < 1 OR pg_catalog.length(v_grund) > 500 THEN
            RAISE EXCEPTION 'Grund for widerrufen must be between 1 and 500 non-blank characters'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    -- Lock treatment row to serialize inspection events for this treatment
    SELECT *
    INTO v_behandlung
    FROM public.podologie_behandlungen
    WHERE id = p_behandlung_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Treatment % not found', p_behandlung_id
            USING ERRCODE = 'P0002';
    END IF;

    IF v_behandlung.owner_id IS DISTINCT FROM p_owner_id THEN
        RAISE EXCEPTION 'Treatment belongs to a different owner'
            USING ERRCODE = '42501';
    END IF;

    IF v_behandlung.storniert_am IS NOT NULL THEN
        RAISE EXCEPTION 'Treatment % is cancelled (storniert)', p_behandlung_id
            USING ERRCODE = '23514';
    END IF;

    IF v_behandlung.hpnr_codes IS NULL OR NOT (v_behandlung.hpnr_codes @> ARRAY['78040'::text]) THEN
        RAISE EXCEPTION 'Treatment does not contain 78040 in hpnr_codes'
            USING ERRCODE = '23514';
    END IF;

    IF v_behandlung.verordnung_id IS NULL THEN
        RAISE EXCEPTION 'Treatment verordnung_id must not be null'
            USING ERRCODE = '23514';
    END IF;

    -- Determine latest predecessor event for this treatment
    SELECT *
    INTO v_prev
    FROM public.podologie_empfangsnachweise
    WHERE behandlung_id = p_behandlung_id
    ORDER BY event_seq DESC
    LIMIT 1;

    IF FOUND THEN
        v_vorgaenger_id := v_prev.id;
    ELSE
        v_vorgaenger_id := NULL;
    END IF;

    -- Handle withdrawal predecessor inheritance and initial checks
    IF p_status = 'widerrufen' THEN
        IF v_vorgaenger_id IS NULL THEN
            RAISE EXCEPTION 'Withdrawal requires an existing predecessor event'
                USING ERRCODE = '23514';
        END IF;

        IF p_therapeuteninitialen IS NULL THEN
            v_initialen := v_prev.therapeuteninitialen;
        ELSE
            v_initialen := pg_catalog.btrim(p_therapeuteninitialen, E' \t\r\n');
            IF pg_catalog.length(v_initialen) < 1 OR pg_catalog.length(v_initialen) > 16 THEN
                RAISE EXCEPTION 'Therapeuteninitialen must be between 1 and 16 non-blank characters'
                    USING ERRCODE = '23514';
            END IF;
        END IF;

        IF p_dokument_id IS NULL THEN
            v_dokument_id := v_prev.dokument_id;
        ELSE
            v_dokument_id := p_dokument_id;
        END IF;
    ELSE
        v_dokument_id := p_dokument_id;
    END IF;

    -- Validate document existence if explicitly provided or non-null
    IF p_dokument_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1
            FROM public.prescription_documents
            WHERE id = p_dokument_id
              AND owner_id = p_owner_id
              AND prescription_id = v_behandlung.verordnung_id
        ) THEN
            RAISE EXCEPTION 'Prescription document % not found for owner and verordnung', p_dokument_id
                USING ERRCODE = 'P0002';
        END IF;
    END IF;

    -- Derive current timestamp strictly after lock acquisition
    v_now := pg_catalog.clock_timestamp();

    -- Append new immutable inspection event
    INSERT INTO public.podologie_empfangsnachweise (
        owner_id,
        behandlung_id,
        behandlungsdatum,
        hpnr_code,
        therapeuteninitialen,
        status,
        geprueft_von,
        geprueft_am,
        dokument_id,
        grund,
        vorgaenger_id
    ) VALUES (
        p_owner_id,
        p_behandlung_id,
        v_behandlung.behandlungsdatum,
        '78040',
        v_initialen,
        p_status,
        p_pruefer_id,
        v_now,
        v_dokument_id,
        v_grund,
        v_vorgaenger_id
    ) RETURNING * INTO v_result;

    RETURN v_result;
END;
$function$
;
ALTER FUNCTION public.podologie_empfangsnachweis_append(p_owner_id uuid, p_pruefer_id uuid, p_behandlung_id uuid, p_status text, p_therapeuteninitialen text, p_dokument_id bigint, p_grund text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.podologie_empfangsnachweise_prevent_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
    RAISE EXCEPTION 'podologie_empfangsnachweise is strictly append-only: UPDATE and DELETE are forbidden'
        USING ERRCODE = '42501';
END;
$function$
;
ALTER FUNCTION public.podologie_empfangsnachweise_prevent_mutation() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.prescriptions_festschreibung()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.belegnummer is null then
    return new;
  end if;

  if new.owner_id             is distinct from old.owner_id
  or new.business_id          is distinct from old.business_id
  or new.created_at           is distinct from old.created_at
  or new.belegnummer          is distinct from old.belegnummer
  or new.ausstellungsdatum    is distinct from old.ausstellungsdatum
  or new.diagnosegruppe       is distinct from old.diagnosegruppe
  or new.icd10                is distinct from old.icd10
  or new.icd10_2              is distinct from old.icd10_2
  or new.leitsymptomatik      is distinct from old.leitsymptomatik
  or new.pat_leitsymptomatik  is distinct from old.pat_leitsymptomatik
  or new.is_dringend          is distinct from old.is_dringend
  or new.hausbesuch           is distinct from old.hausbesuch
  or new.frequenz             is distinct from old.frequenz
  or new.rezeptart            is distinct from old.rezeptart
  or new.zuzahlung_befreit    is distinct from old.zuzahlung_befreit
  or new.zuzahlung_eur        is distinct from old.zuzahlung_eur
  or new.kostentraeger_ik     is distinct from old.kostentraeger_ik
  or new.arzt_id              is distinct from old.arzt_id
  or new.wagner_grad          is distinct from old.wagner_grad
  or new.nagel                is distinct from old.nagel
  or new.krankenkasse_ik      is distinct from old.krankenkasse_ik
  or new.behandlungsanlass    is distinct from old.behandlungsanlass
  or new.heilmittel           is distinct from old.heilmittel
  or new.heilmittel_position  is distinct from old.heilmittel_position
  or new.anzahl_einheiten     is distinct from old.anzahl_einheiten
  or new.doctor_lanr          is distinct from old.doctor_lanr
  or new.doctor_bsnr          is distinct from old.doctor_bsnr
  or new.rezept_typ           is distinct from old.rezept_typ
  or new.is_blanko            is distinct from old.is_blanko
  or new.is_lhb_bvb           is distinct from old.is_lhb_bvb
  or new.behandlungsbeginn    is distinct from old.behandlungsbeginn
  or new.gueltig_bis          is distinct from old.gueltig_bis
  then
    raise exception 'Eingereichte Verordnung ist festgeschrieben (GoBD, §302 SGB V). Offen bleiben nur status/absetzung_*/storno_*/zuzahlung_kassiert_* und die Anonymisierung.';
  end if;

  if new.patient_name is not null and new.patient_name is distinct from old.patient_name then
    raise exception 'patient_name darf nur auf NULL gesetzt werden (Anonymisierung).';
  end if;
  if new.versichertennummer is not null and new.versichertennummer is distinct from old.versichertennummer then
    raise exception 'versichertennummer darf nur auf NULL gesetzt werden (Anonymisierung).';
  end if;
  if new.patient_id is not null and new.patient_id is distinct from old.patient_id then
    raise exception 'patient_id darf nur auf NULL gesetzt werden (Anonymisierung).';
  end if;

  new.updated_at := timezone('utc', now());
  return new;
end $function$
;
ALTER FUNCTION public.prescriptions_festschreibung() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.prescriptions_mandant_pruefen()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.patient_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.leads l
        WHERE l.id = NEW.patient_id AND l.owner_id = NEW.owner_id) THEN
    RAISE EXCEPTION 'Patient gehört nicht zu dieser Praxis.' USING ERRCODE = '42501';
  END IF;
  IF NEW.arzt_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.aerzte a
        WHERE a.id = NEW.arzt_id AND a.owner_id = NEW.owner_id) THEN
    RAISE EXCEPTION 'Arzt gehört nicht zu dieser Praxis.' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$
;
ALTER FUNCTION public.prescriptions_mandant_pruefen() OWNER TO postgres;

