CREATE OR REPLACE FUNCTION public.profiles_privilegierte_spalten_schuetzen()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    RAISE EXCEPTION 'Profile werden nur serverseitig angelegt.'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.owner_id                     IS DISTINCT FROM OLD.owner_id
  OR NEW.role                         IS DISTINCT FROM OLD.role
  OR NEW.plan                         IS DISTINCT FROM OLD.plan
  OR NEW.plan_status                  IS DISTINCT FROM OLD.plan_status
  OR NEW.trial_ends_at                IS DISTINCT FROM OLD.trial_ends_at
  OR NEW.current_period_end           IS DISTINCT FROM OLD.current_period_end
  OR NEW.stripe_customer_id           IS DISTINCT FROM OLD.stripe_customer_id
  OR NEW.stripe_subscription_id       IS DISTINCT FROM OLD.stripe_subscription_id
  OR NEW.stripe_price_id              IS DISTINCT FROM OLD.stripe_price_id
  OR NEW.is_active                    IS DISTINCT FROM OLD.is_active
  OR NEW.activated_at                 IS DISTINCT FROM OLD.activated_at
  OR NEW.deletion_scheduled_at        IS DISTINCT FROM OLD.deletion_scheduled_at
  OR NEW.dta_pro_subscription_item_id IS DISTINCT FROM OLD.dta_pro_subscription_item_id
  THEN
    RAISE EXCEPTION 'Diese Profilfelder können nur serverseitig geändert werden.'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.company_code IS DISTINCT FROM OLD.company_code THEN
    IF OLD.company_code IS NOT NULL
       OR NEW.company_code IS NULL
       OR NEW.company_code <> upper(NEW.company_code) THEN
      RAISE EXCEPTION 'Der Praxiscode kann nur einmal und nur in Großbuchstaben gesetzt werden.'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;
ALTER FUNCTION public.profiles_privilegierte_spalten_schuetzen() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.pruefe_abrechnung_zuzahlungsforderung()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner_id uuid;
  v_business_id uuid;
  v_abrechnung_id uuid;
  v_herkunft text;
  v_original_vkz text;
  v_parent_owner_id uuid;
  v_parent_business_id uuid;
  v_prescription_id uuid;
  v_leistungen jsonb;
  v_daten jsonb;
  v_position jsonb;
  v_seen integer[] := ARRAY[]::integer[];
  v_index integer;
  v_proof_date date;
  v_original_kostentraeger_ik text;
  v_patient_id uuid;
  v_proof jsonb;
  v_gueltig_ab date;
  v_gueltig_bis date;
  v_geprueft_am date;
  v_geprueft_zeitpunkt timestamptz;
  v_status_wechsel_datum date;
  v_za_datum date;
  v_versand_datum date;
  v_mahnung_faelligkeit date;
  v_zeile_status text;
BEGIN
  -- SECURITY INVOKER keeps current_user equal to effective PostgREST role.
  -- Do not use SECURITY DEFINER or trust user-editable request metadata.
  -- VKZ03 operations require backend execution (service_role or postgres).
  -- Existing abrechnung_owner_all allows authenticated tenant users to write
  -- ordinary headers, but VKZ03 reservations, updates, and deletes must be
  -- restricted to backend roles to prevent unauthorized status/totals/storage tampering.
  IF (TG_OP = 'DELETE' AND OLD.verarbeitungskennzeichen = '03')
     OR (TG_OP = 'UPDATE' AND (OLD.verarbeitungskennzeichen = '03' OR NEW.verarbeitungskennzeichen = '03'))
     OR (TG_OP = 'INSERT' AND NEW.verarbeitungskennzeichen = '03') THEN
    IF current_user NOT IN ('service_role', 'postgres') THEN
      RAISE EXCEPTION 'VKZ03 operations require backend execution'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.verarbeitungskennzeichen = '03' THEN
      RAISE EXCEPTION 'VKZ03 claim reservation must be retained; retry the same claim'
        USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;

  -- Never relabel historical files or change established claim identity.
  -- NULL legacy headers also cannot be silently converted to VKZ03.
  IF TG_OP = 'UPDATE' THEN
    IF NEW.verarbeitungskennzeichen IS DISTINCT FROM OLD.verarbeitungskennzeichen
       OR NEW.zuzahlungsforderung_ursprung_id
          IS DISTINCT FROM OLD.zuzahlungsforderung_ursprung_id
       OR NEW.zuzahlungsforderung_daten
          IS DISTINCT FROM OLD.zuzahlungsforderung_daten THEN
      RAISE EXCEPTION 'Abrechnung processing code and source linkage are immutable'
        USING ERRCODE = '23514';
    END IF;

    IF OLD.verarbeitungskennzeichen = '03' THEN
      IF (NEW.owner_id IS DISTINCT FROM OLD.owner_id
          OR NEW.business_id IS DISTINCT FROM OLD.business_id
          OR NEW.kostentraeger_ik IS DISTINCT FROM OLD.kostentraeger_ik
          OR NEW.id IS DISTINCT FROM OLD.id) THEN
        RAISE EXCEPTION 'VKZ03 claim tenant, location and identity are immutable'
          USING ERRCODE = '23514';
      END IF;

      -- Finalized claim rewind protection:
      -- Presence of immutable claim snapshot in abrechnung_zeile is the durable completion marker.
      IF EXISTS (SELECT 1 FROM public.abrechnung_zeile z WHERE z.abrechnung_id = OLD.id) THEN
        IF NEW.status = 'verworfen' THEN
          RAISE EXCEPTION 'VKZ03 finalized claim cannot be discarded (verworfen)'
            USING ERRCODE = '23514';
        END IF;

        IF OLD.status IS DISTINCT FROM 'erstellt' AND NEW.status = 'erstellt' THEN
          RAISE EXCEPTION 'VKZ03 finalized claim cannot rewind to erstellt'
            USING ERRCODE = '23514';
        END IF;
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  IF NEW.verarbeitungskennzeichen IS DISTINCT FROM '03' THEN
    RETURN NEW;
  END IF;

  SELECT z.owner_id, z.business_id, z.abrechnung_id, z.herkunft,
         a.verarbeitungskennzeichen, z.prescription_id, z.leistungen,
         a.owner_id, a.business_id, a.kostentraeger_ik, z.status
    INTO v_owner_id, v_business_id, v_abrechnung_id, v_herkunft, v_original_vkz,
         v_prescription_id, v_leistungen, v_parent_owner_id, v_parent_business_id,
         v_original_kostentraeger_ik, v_zeile_status
    FROM public.abrechnung_zeile z
    JOIN public.abrechnung a ON a.id = z.abrechnung_id
   WHERE z.id = NEW.zuzahlungsforderung_ursprung_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'VKZ03 original claim line not found or not accessible'
      USING ERRCODE = '23503';
  END IF;

  IF v_parent_owner_id IS DISTINCT FROM v_owner_id
     OR v_parent_business_id IS DISTINCT FROM v_business_id THEN
    RAISE EXCEPTION 'VKZ03 original header and line tenant or location mismatch'
      USING ERRCODE = '23514';
  END IF;

  -- Preserve original location identity even when NULL: the standard trigger
  -- has just supplied today's default, which is not historical evidence.
  IF TG_OP = 'INSERT' AND v_business_id IS NULL THEN
    NEW.business_id := NULL;
  END IF;

  IF NEW.owner_id IS DISTINCT FROM v_owner_id
     OR NEW.business_id IS DISTINCT FROM v_business_id THEN
    RAISE EXCEPTION 'VKZ03 original claim must belong to same tenant and location'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.kostentraeger_ik IS DISTINCT FROM v_original_kostentraeger_ik THEN
    RAISE EXCEPTION 'VKZ03 kostentraeger_ik must match original claim header'
      USING ERRCODE = '23514';
  END IF;

  IF v_abrechnung_id = NEW.id OR v_herkunft IS DISTINCT FROM 'einreichung'
     OR v_zeile_status IS DISTINCT FROM 'akzeptiert'
     OR (v_original_vkz IS NOT NULL AND v_original_vkz <> '01') THEN
    RAISE EXCEPTION 'VKZ03 requires a genuine original VKZ01 submission'
      USING ERRCODE = '23514';
  END IF;

  IF v_prescription_id IS NOT NULL THEN
    SELECT p.patient_id
      INTO v_patient_id
      FROM public.prescriptions p
     WHERE p.id = v_prescription_id
       AND p.owner_id = NEW.owner_id;
  END IF;

  -- Reservation proof metadata validation (INSERT only).
  v_daten := NEW.zuzahlungsforderung_daten;
  IF jsonb_typeof(v_daten) IS DISTINCT FROM 'object'
     OR (v_daten - ARRAY['grund', 'nachweisDatum', 'positionIndices',
                         'bestaetigt', 'mahnungId', 'nachweisDokumentId',
                         'nachweisPruefung']) <> '{}'::jsonb
     OR jsonb_typeof(v_daten->'grund') IS DISTINCT FROM 'string'
     OR (v_daten->>'grund') NOT IN ('1', '2', '5')
     OR v_daten->'bestaetigt' IS DISTINCT FROM 'true'::jsonb
     OR jsonb_typeof(v_daten->'nachweisDatum') IS DISTINCT FROM 'string'
     OR (v_daten->>'nachweisDatum') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     OR jsonb_typeof(v_daten->'positionIndices') IS DISTINCT FROM 'array'
     OR ((v_daten->>'grund') = '2' AND NOT (v_daten ? 'mahnungId'))
     OR NOT (v_daten ? 'nachweisPruefung') THEN
    RAISE EXCEPTION 'Invalid VKZ03 frozen intent metadata'
      USING ERRCODE = '23514';
  END IF;

  BEGIN
    v_proof_date := (v_daten->>'nachweisDatum')::date;
  EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
    RAISE EXCEPTION 'Invalid VKZ03 proof date' USING ERRCODE = '23514';
  END;
  IF v_proof_date > (CURRENT_TIMESTAMP AT TIME ZONE 'Europe/Berlin')::date THEN
    RAISE EXCEPTION 'VKZ03 proof date must not be in future'
      USING ERRCODE = '23514';
  END IF;

  IF jsonb_array_length(v_daten->'positionIndices') = 0
     OR jsonb_typeof(v_leistungen) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'VKZ03 requires original session indices'
      USING ERRCODE = '23514';
  END IF;
  FOR v_position IN SELECT value FROM jsonb_array_elements(v_daten->'positionIndices') LOOP
    IF jsonb_typeof(v_position) <> 'number'
       OR (v_position #>> '{}') !~ '^(0|[1-9][0-9]{0,5})$' THEN
      RAISE EXCEPTION 'Invalid VKZ03 original session index' USING ERRCODE = '23514';
    END IF;
    v_index := (v_position #>> '{}')::integer;
    IF v_index >= jsonb_array_length(v_leistungen) OR v_index = ANY(v_seen) THEN
      RAISE EXCEPTION 'VKZ03 original session index missing or duplicated'
        USING ERRCODE = '23514';
    END IF;
    v_seen := array_append(v_seen, v_index);
  END LOOP;

  IF v_daten ? 'nachweisDokumentId' THEN
    IF jsonb_typeof(v_daten->'nachweisDokumentId') IS DISTINCT FROM 'string'
       OR (v_daten->>'nachweisDokumentId') !~ '^[1-9][0-9]{0,17}$' THEN
      RAISE EXCEPTION 'Invalid VKZ03 proof document identifier' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.prescription_documents d
                    WHERE d.id = (v_daten->>'nachweisDokumentId')::bigint
                      AND d.owner_id = NEW.owner_id
                      AND d.prescription_id = v_prescription_id
                      AND (d.business_id IS NULL
                           OR d.business_id = v_business_id)
                      AND (d.patient_id IS NULL
                           OR d.patient_id = v_patient_id)) THEN
      RAISE EXCEPTION 'VKZ03 proof document must belong to original prescription'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  v_proof := v_daten->'nachweisPruefung';
  IF jsonb_typeof(v_proof) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Invalid VKZ03 proof object' USING ERRCODE = '23514';
  END IF;

  IF (v_daten->>'grund') = '1' THEN
    IF (v_proof - ARRAY['art', 'referenz', 'gueltigAb', 'gueltigBis',
                        'geprueftAm', 'geprueftZeitpunkt', 'prueferId',
                        'patientId', 'kostentraegerIk', 'bestaetigt']) <> '{}'::jsonb
       OR NOT (v_proof ? 'art' AND v_proof ? 'referenz' AND v_proof ? 'gueltigAb'
               AND v_proof ? 'gueltigBis' AND v_proof ? 'geprueftAm'
               AND v_proof ? 'geprueftZeitpunkt' AND v_proof ? 'prueferId'
               AND v_proof ? 'patientId' AND v_proof ? 'kostentraegerIk'
               AND v_proof ? 'bestaetigt') THEN
      RAISE EXCEPTION 'Invalid VKZ03 proof metadata keys for grund 1'
        USING ERRCODE = '23514';
    END IF;

    IF (v_proof->>'art') IS DISTINCT FROM 'belastungsgrenze62' THEN
      RAISE EXCEPTION 'VKZ03 proof art must be belastungsgrenze62 for grund 1'
        USING ERRCODE = '23514';
    END IF;

  ELSIF (v_daten->>'grund') = '2' THEN
    IF (v_proof - ARRAY['art', 'referenz', 'geprueftAm', 'geprueftZeitpunkt',
                        'prueferId', 'patientId', 'kostentraegerIk', 'bestaetigt',
                        'versandDatum', 'versandArt', 'nachweisBeigefuegtBestaetigt',
                        'erfolgloserEinzugBestaetigt']) <> '{}'::jsonb
       OR NOT (v_proof ? 'art' AND v_proof ? 'referenz' AND v_proof ? 'geprueftAm'
               AND v_proof ? 'geprueftZeitpunkt' AND v_proof ? 'prueferId'
               AND v_proof ? 'patientId' AND v_proof ? 'kostentraegerIk'
               AND v_proof ? 'bestaetigt' AND v_proof ? 'versandDatum'
               AND v_proof ? 'versandArt' AND v_proof ? 'nachweisBeigefuegtBestaetigt'
               AND v_proof ? 'erfolgloserEinzugBestaetigt') THEN
      RAISE EXCEPTION 'Invalid VKZ03 proof metadata keys for grund 2'
        USING ERRCODE = '23514';
    END IF;

    IF (v_proof->>'art') IS DISTINCT FROM 'zahlungsaufforderung43c' THEN
      RAISE EXCEPTION 'VKZ03 proof art must be zahlungsaufforderung43c for grund 2'
        USING ERRCODE = '23514';
    END IF;

  ELSIF (v_daten->>'grund') = '5' THEN
    IF (v_proof - ARRAY['art', 'referenz', 'gueltigAb', 'gueltigBis',
                        'geprueftAm', 'geprueftZeitpunkt', 'prueferId',
                        'patientId', 'kostentraegerIk', 'bestaetigt',
                        'statusWechselDatum', 'zahlungsaufforderungReferenz',
                        'zahlungsaufforderungDatum', 'originalAbzugBestaetigt']) <> '{}'::jsonb
       OR NOT (v_proof ? 'art' AND v_proof ? 'referenz' AND v_proof ? 'gueltigAb'
               AND v_proof ? 'gueltigBis' AND v_proof ? 'geprueftAm'
               AND v_proof ? 'geprueftZeitpunkt' AND v_proof ? 'prueferId'
               AND v_proof ? 'patientId' AND v_proof ? 'kostentraegerIk'
               AND v_proof ? 'bestaetigt' AND v_proof ? 'statusWechselDatum'
               AND v_proof ? 'zahlungsaufforderungReferenz'
               AND v_proof ? 'zahlungsaufforderungDatum'
               AND v_proof ? 'originalAbzugBestaetigt') THEN
      RAISE EXCEPTION 'Invalid VKZ03 proof metadata keys for grund 5'
        USING ERRCODE = '23514';
    END IF;

    IF (v_proof->>'art') IS DISTINCT FROM 'statuswechsel_jahreswechsel' THEN
      RAISE EXCEPTION 'VKZ03 proof art must be statuswechsel_jahreswechsel for grund 5'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF jsonb_typeof(v_proof->'referenz') IS DISTINCT FROM 'string'
     OR (v_proof->>'referenz') = ''
     OR length(v_proof->>'referenz') > 240
     OR btrim(v_proof->>'referenz') <> (v_proof->>'referenz') THEN
    RAISE EXCEPTION 'Invalid VKZ03 proof reference'
      USING ERRCODE = '23514';
  END IF;

  IF jsonb_typeof(v_proof->'geprueftAm') IS DISTINCT FROM 'string'
     OR (v_proof->>'geprueftAm') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
    RAISE EXCEPTION 'Invalid VKZ03 proof geprueftAm date format'
      USING ERRCODE = '23514';
  END IF;

  BEGIN
    v_geprueft_am := (v_proof->>'geprueftAm')::date;
  EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
    RAISE EXCEPTION 'Invalid VKZ03 proof geprueftAm date' USING ERRCODE = '23514';
  END;

  IF v_geprueft_am > (CURRENT_TIMESTAMP AT TIME ZONE 'Europe/Berlin')::date THEN
    RAISE EXCEPTION 'VKZ03 proof geprueftAm date must not be in future'
      USING ERRCODE = '23514';
  END IF;

  IF jsonb_typeof(v_proof->'geprueftZeitpunkt') IS DISTINCT FROM 'string'
     OR (v_proof->>'geprueftZeitpunkt') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.[0-9]+)?Z$' THEN
    RAISE EXCEPTION 'Invalid VKZ03 proof inspection timestamp (strict UTC required)'
      USING ERRCODE = '23514';
  END IF;

  BEGIN
    v_geprueft_zeitpunkt := (v_proof->>'geprueftZeitpunkt')::timestamptz;
  EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
    RAISE EXCEPTION 'Invalid VKZ03 proof inspection timestamp' USING ERRCODE = '23514';
  END;

  IF v_geprueft_zeitpunkt > CURRENT_TIMESTAMP THEN
    RAISE EXCEPTION 'VKZ03 proof inspection timestamp must not be in future'
      USING ERRCODE = '23514';
  END IF;

  IF (v_geprueft_zeitpunkt AT TIME ZONE 'Europe/Berlin')::date <> v_geprueft_am THEN
    RAISE EXCEPTION 'VKZ03 proof inspection timestamp must match geprueftAm date in Europe/Berlin'
      USING ERRCODE = '23514';
  END IF;

  IF jsonb_typeof(v_proof->'prueferId') IS DISTINCT FROM 'string'
     OR (v_proof->>'prueferId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR (v_proof->>'prueferId')::uuid IS DISTINCT FROM NEW.owner_id THEN
    RAISE EXCEPTION 'VKZ03 proof prueferId must match owner'
      USING ERRCODE = '23514';
  END IF;

  IF jsonb_typeof(v_proof->'patientId') IS DISTINCT FROM 'string'
     OR (v_proof->>'patientId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR v_patient_id IS NULL
     OR (v_proof->>'patientId')::uuid IS DISTINCT FROM v_patient_id THEN
    RAISE EXCEPTION 'VKZ03 proof patientId must match original prescription'
      USING ERRCODE = '23514';
  END IF;

  IF jsonb_typeof(v_proof->'kostentraegerIk') IS DISTINCT FROM 'string'
     OR (v_proof->>'kostentraegerIk') !~ '^[0-9]{9}$'
     OR (v_proof->>'kostentraegerIk') IS DISTINCT FROM v_original_kostentraeger_ik THEN
    RAISE EXCEPTION 'VKZ03 proof kostentraegerIk must match original claim header IK'
      USING ERRCODE = '23514';
  END IF;

  IF v_proof->'bestaetigt' IS DISTINCT FROM 'true'::jsonb THEN
    RAISE EXCEPTION 'VKZ03 proof confirmation must be strict boolean true'
      USING ERRCODE = '23514';
  END IF;

  -- Period validation applies ONLY to grounds 1 and 5 (ground 2 has no gueltigAb/gueltigBis)
  IF (v_daten->>'grund') IN ('1', '5') THEN
    IF jsonb_typeof(v_proof->'gueltigAb') IS DISTINCT FROM 'string'
       OR (v_proof->>'gueltigAb') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
       OR jsonb_typeof(v_proof->'gueltigBis') IS DISTINCT FROM 'string'
       OR (v_proof->>'gueltigBis') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
      RAISE EXCEPTION 'Invalid VKZ03 proof validity dates format'
        USING ERRCODE = '23514';
    END IF;

    BEGIN
      v_gueltig_ab := (v_proof->>'gueltigAb')::date;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
      RAISE EXCEPTION 'Invalid VKZ03 proof gueltigAb date' USING ERRCODE = '23514';
    END;

    BEGIN
      v_gueltig_bis := (v_proof->>'gueltigBis')::date;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
      RAISE EXCEPTION 'Invalid VKZ03 proof gueltigBis date' USING ERRCODE = '23514';
    END;

    IF v_gueltig_bis < v_gueltig_ab THEN
      RAISE EXCEPTION 'VKZ03 proof validity period end must be on or after start'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF (v_daten->>'grund') = '5' THEN
    IF jsonb_typeof(v_proof->'statusWechselDatum') IS DISTINCT FROM 'string'
       OR (v_proof->>'statusWechselDatum') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
      RAISE EXCEPTION 'Invalid VKZ03 status change date format'
        USING ERRCODE = '23514';
    END IF;

    BEGIN
      v_status_wechsel_datum := (v_proof->>'statusWechselDatum')::date;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
      RAISE EXCEPTION 'Invalid VKZ03 status change date' USING ERRCODE = '23514';
    END;

    IF v_status_wechsel_datum > (CURRENT_TIMESTAMP AT TIME ZONE 'Europe/Berlin')::date THEN
      RAISE EXCEPTION 'VKZ03 status change date must not be in future'
        USING ERRCODE = '23514';
    END IF;

    IF v_status_wechsel_datum <= v_gueltig_bis THEN
      RAISE EXCEPTION 'VKZ03 status change date must be after exemption period end'
        USING ERRCODE = '23514';
    END IF;

    IF jsonb_typeof(v_proof->'zahlungsaufforderungReferenz') IS DISTINCT FROM 'string'
       OR (v_proof->>'zahlungsaufforderungReferenz') = ''
       OR length(v_proof->>'zahlungsaufforderungReferenz') > 240
       OR btrim(v_proof->>'zahlungsaufforderungReferenz') <> (v_proof->>'zahlungsaufforderungReferenz') THEN
      RAISE EXCEPTION 'Invalid VKZ03 payment request reference'
        USING ERRCODE = '23514';
    END IF;

    IF jsonb_typeof(v_proof->'zahlungsaufforderungDatum') IS DISTINCT FROM 'string'
       OR (v_proof->>'zahlungsaufforderungDatum') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
      RAISE EXCEPTION 'Invalid VKZ03 payment request date format'
        USING ERRCODE = '23514';
    END IF;

    BEGIN
      v_za_datum := (v_proof->>'zahlungsaufforderungDatum')::date;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
      RAISE EXCEPTION 'Invalid VKZ03 payment request date' USING ERRCODE = '23514';
    END;

    IF v_za_datum > (CURRENT_TIMESTAMP AT TIME ZONE 'Europe/Berlin')::date THEN
      RAISE EXCEPTION 'VKZ03 payment request date must not be in future'
        USING ERRCODE = '23514';
    END IF;

    IF v_za_datum > v_proof_date THEN
      RAISE EXCEPTION 'VKZ03 payment request date must be on or before proof date'
        USING ERRCODE = '23514';
    END IF;

    IF v_za_datum < v_status_wechsel_datum THEN
      RAISE EXCEPTION 'VKZ03 payment request date must be on or after status change date'
        USING ERRCODE = '23514';
    END IF;

    IF v_proof->'originalAbzugBestaetigt' IS DISTINCT FROM 'true'::jsonb THEN
      RAISE EXCEPTION 'VKZ03 original deduction confirmation must be strict boolean true'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF (v_daten->>'grund') = '2' THEN
    IF jsonb_typeof(v_proof->'versandDatum') IS DISTINCT FROM 'string'
       OR (v_proof->>'versandDatum') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
      RAISE EXCEPTION 'Invalid VKZ03 dispatch date format'
        USING ERRCODE = '23514';
    END IF;

    BEGIN
      v_versand_datum := (v_proof->>'versandDatum')::date;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
      RAISE EXCEPTION 'Invalid VKZ03 dispatch date' USING ERRCODE = '23514';
    END;

    IF v_versand_datum > (CURRENT_TIMESTAMP AT TIME ZONE 'Europe/Berlin')::date THEN
      RAISE EXCEPTION 'VKZ03 dispatch date must not be in future'
        USING ERRCODE = '23514';
    END IF;

    IF v_versand_datum <> v_proof_date OR v_versand_datum > v_geprueft_am THEN
      RAISE EXCEPTION 'VKZ03 dispatch date must match proof date'
        USING ERRCODE = '23514';
    END IF;

    IF jsonb_typeof(v_proof->'versandArt') IS DISTINCT FROM 'string'
       OR (v_proof->>'versandArt') NOT IN ('post', 'elektronisch', 'persoenlich') THEN
      RAISE EXCEPTION 'Invalid VKZ03 dispatch type'
        USING ERRCODE = '23514';
    END IF;

    IF v_proof->'nachweisBeigefuegtBestaetigt' IS DISTINCT FROM 'true'::jsonb THEN
      RAISE EXCEPTION 'VKZ03 proof attached confirmation must be strict boolean true'
        USING ERRCODE = '23514';
    END IF;

    IF v_proof->'erfolgloserEinzugBestaetigt' IS DISTINCT FROM 'true'::jsonb THEN
      RAISE EXCEPTION 'VKZ03 unsuccessful collection confirmation must be strict boolean true'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_daten ? 'mahnungId' THEN
    IF jsonb_typeof(v_daten->'mahnungId') IS DISTINCT FROM 'string'
       OR (v_daten->>'mahnungId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'Invalid VKZ03 notice identifier' USING ERRCODE = '23514';
    END IF;

    SELECT COALESCE(m.neue_faelligkeit, m.original_faelligkeit)
      INTO v_mahnung_faelligkeit
      FROM public.mahnungen m
     WHERE m.id = (v_daten->>'mahnungId')::uuid
       AND m.owner_id = NEW.owner_id
       AND m.prescription_id = v_prescription_id
       AND m.patient_id = v_patient_id
       AND m.ausfallrechnung_id IS NULL
       AND m.status = 'offen';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'VKZ03 notice must belong to original prescription'
        USING ERRCODE = '23514';
    END IF;

    IF v_mahnung_faelligkeit IS NULL
       OR v_mahnung_faelligkeit >= (CURRENT_TIMESTAMP AT TIME ZONE 'Europe/Berlin')::date THEN
      RAISE EXCEPTION 'VKZ03 notice deadline has not expired'
        USING ERRCODE = '23514';
    END IF;

    IF (v_daten->>'grund') = '2' AND v_versand_datum > v_mahnung_faelligkeit THEN
      RAISE EXCEPTION 'VKZ03 dispatch date must be on or before notice deadline'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;
ALTER FUNCTION public.pruefe_abrechnung_zuzahlungsforderung() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.pruefe_booking_leistung_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE b_owner uuid;
BEGIN
  SELECT owner_id INTO b_owner FROM public.bookings WHERE id = NEW.booking_id;
  IF b_owner IS DISTINCT FROM NEW.owner_id THEN
    RAISE EXCEPTION 'Termin gehoert einem anderen Inhaber' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $function$
;
ALTER FUNCTION public.pruefe_booking_leistung_owner() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.pruefe_booking_verordnung_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_owner uuid;
BEGIN
  IF NEW.verordnung_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT owner_id INTO v_owner FROM prescriptions WHERE id = NEW.verordnung_id;

  IF v_owner IS NULL OR v_owner IS DISTINCT FROM NEW.owner_id THEN
    RAISE EXCEPTION 'Diese Verordnung gehoert zu einer anderen Praxis.'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$
;
ALTER FUNCTION public.pruefe_booking_verordnung_owner() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.pruefe_rechnung_zahlung_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner uuid;
BEGIN
  SELECT owner_id INTO v_owner FROM public.invoices WHERE id = NEW.invoice_id;
  IF v_owner IS NOT NULL AND v_owner <> NEW.owner_id THEN
    RAISE EXCEPTION 'Die Rechnung gehoert einem anderen Inhaber.'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$
;
ALTER FUNCTION public.pruefe_rechnung_zahlung_owner() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.public_praxis_sector(p_owner_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select p.sector
  from profiles p
  where p.id = p_owner_id
  limit 1;
$function$
;
ALTER FUNCTION public.public_praxis_sector(p_owner_id uuid) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.rechnung_zahlung_buchen(p_invoice_id uuid, p_owner_id uuid, p_created_by uuid, p_betrag_eur numeric, p_zahlungsdatum date, p_gegenkonto_code text, p_gegenkonto_label text, p_restbetrag_modus text, p_ausbuchungskonto_code text DEFAULT NULL::text, p_ausbuchungskonto_label text DEFAULT NULL::text, p_bemerkung text DEFAULT NULL::text, p_zahlart text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inv           record;
  v_rx_id         uuid;
  v_gebucht       numeric(10,2);
  v_offen         numeric(10,2);
  v_rest          numeric(10,2);
  v_ausbuchen     boolean;
  v_zahlung_id    uuid;
  v_ausbuchung_id uuid;
  v_beleg_nr      bigint := NULL;
  v_status        text;
  v_rx            record;
BEGIN
  -- 1. Rechnung sperren. Ohne diese Sperre lesen zwei gleichzeitige Buchungen
  --    denselben offenen Betrag und buchen beide.
  SELECT id, owner_id, status, payment_status, total_patient,
         patient_id, invoice_number,
         COALESCE(prescription_id, verordnung_id) AS rezept_id
    INTO v_inv
    FROM public.invoices
   WHERE id = p_invoice_id
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Rechnung nicht gefunden.' USING ERRCODE = 'no_data_found';
  END IF;

  IF v_inv.owner_id <> p_owner_id THEN
    RAISE EXCEPTION 'Die Rechnung gehoert einem anderen Inhaber.' USING ERRCODE = '42501';
  END IF;

  IF v_inv.status = 'cancelled' THEN
    RAISE EXCEPTION 'Auf eine stornierte Rechnung kann nicht gebucht werden.'
      USING ERRCODE = 'check_violation';
  END IF;

  IF COALESCE(v_inv.total_patient, 0) <= 0 THEN
    RAISE EXCEPTION 'Die Rechnung hat keinen Betrag (total_patient).'
      USING ERRCODE = 'check_violation';
  END IF;

  -- 1b. Zahlart ist seit Ops #271 Pflicht — sie entscheidet, ob/als was der
  --     Beleg entsteht. Ein fehlender Wert soll die Buchung ablehnen, nicht
  --     still als 'sonstiges' durchrutschen (das Backend loest ihn immer aus
  --     der Konto-Kategorie auf, siehe rechnung-zahlung.routes.js).
  IF p_zahlart IS NULL OR p_zahlart NOT IN ('bar','ec','ueberweisung','paypal','sonstiges') THEN
    RAISE EXCEPTION 'Unbekannte oder fehlende Zahlart.' USING ERRCODE = 'check_violation';
  END IF;

  v_rx_id := v_inv.rezept_id;

  -- 2. Was liegt schon im Ledger? sum() ist die Wahrheit, nicht payment_status.
  SELECT COALESCE(sum(betrag_eur), 0)::numeric(10,2)
    INTO v_gebucht
    FROM public.rechnung_zahlungen
   WHERE invoice_id = p_invoice_id;

  -- 2b. Altbestand-Riegel: als bezahlt markiert, aber ohne Beleg. Das entsteht
  --     durch markiereRechnungBezahlt() (module/rechnung-zahlung.js), das
  --     payment_status setzt ohne Ledger-Zeile. Wuerde man hier weiterbuchen,
  --     saehe die Funktion den vollen Betrag als offen und dieselbe Zahlung
  --     liesse sich ein zweites Mal erfassen.
  IF v_gebucht = 0 AND v_inv.payment_status = 'paid' THEN
    RAISE EXCEPTION 'Diese Rechnung gilt bereits als bezahlt, hat aber keinen Zahlungsbeleg. Bitte zuerst klaeren (Backfill), sonst wird dieselbe Zahlung doppelt erfasst.'
      USING ERRCODE = 'check_violation';
  END IF;

  v_offen := (v_inv.total_patient - v_gebucht)::numeric(10,2);

  IF v_offen <= 0 THEN
    RAISE EXCEPTION 'Auf diese Rechnung ist bereits alles gebucht.'
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_betrag_eur IS NULL OR p_betrag_eur <= 0 THEN
    RAISE EXCEPTION 'Der eingegangene Betrag muss ueber 0 EUR liegen.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- 3. Ueberzahlung: harter Riegel, kein Guthaben. "Mehr als die Rechnung" im
  --    Moment der Erfassung ist ein Tippfehler. numeric(10,2) -> exakter
  --    Vergleich, keine Toleranz noetig.
  IF p_betrag_eur > v_offen THEN
    RAISE EXCEPTION 'Mehr als offen: es stehen noch % EUR aus.', to_char(v_offen, 'FM999999990.00')
      USING ERRCODE = 'check_violation';
  END IF;

  v_rest      := (v_offen - p_betrag_eur)::numeric(10,2);
  v_ausbuchen := (p_restbetrag_modus = 'ausbuchen' AND v_rest > 0);

  -- 3b. Eine rezeptgebundene Forderung wird NICHT hier kleingerechnet.
  --     Dafuer gibt es zuzahlung_korrekturen samt Guthaben-Verrechnung und
  --     Protokoll (api-backend/billing/zuzahlung/korrektur.js). Zwei Wege,
  --     dieselbe Forderung zu reduzieren, waeren genau der Zustand, den dieses
  --     Feature vermeiden soll.
  IF v_ausbuchen AND v_rx_id IS NOT NULL THEN
    RAISE EXCEPTION 'Diese Rechnung haengt an einem Rezept — den Restbetrag ueber die Zuzahlungskorrektur reduzieren, nicht hier.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- 4. Die Zahlung selbst.
  INSERT INTO public.rechnung_zahlungen
    (owner_id, invoice_id, art, betrag_eur, zahlungsdatum,
     gegenkonto_code, gegenkonto_label, bemerkung, created_by)
  VALUES
    (p_owner_id, p_invoice_id, 'zahlung', p_betrag_eur,
     COALESCE(p_zahlungsdatum, CURRENT_DATE),
     p_gegenkonto_code, p_gegenkonto_label, p_bemerkung, p_created_by)
  RETURNING id INTO v_zahlung_id;

  -- 5. Restbetrag ausbuchen (nur ohne Rezeptbezug, siehe 3b).
  IF v_ausbuchen THEN
    INSERT INTO public.rechnung_zahlungen
      (owner_id, invoice_id, art, betrag_eur, zahlungsdatum,
       gegenkonto_code, gegenkonto_label, bemerkung, created_by)
    VALUES
      (p_owner_id, p_invoice_id, 'ausbuchung', v_rest,
       COALESCE(p_zahlungsdatum, CURRENT_DATE),
       COALESCE(p_ausbuchungskonto_code, '8700'),
       COALESCE(p_ausbuchungskonto_label, 'Erloesschmaelerung'),
       'Restbetrag ausgebucht', p_created_by)
    RETURNING id INTO v_ausbuchung_id;
  END IF;

  -- 6. Beleg im Journal. Seit Ops #271 (08.09.2026) bei JEDER Zahlart, nicht
  --    mehr nur Bar — belegliste ist ein Belegjournal (kassiereZuzahlung
  --    schreibt dort schon heute ec/ueberweisung, ausfall.routes.js Bank),
  --    das Bar-Kassenbuch (§ 146 AO) ist der zahlart='bar'-Filter im Frontend.
  --    Eine Ausbuchung bleibt OHNE Beleg (kein Geldfluss, unveraendert).
  --
  --    ⚠️ Der `type` beschreibt den GESCHAEFTSVORFALL, nicht den Erfassungsweg:
  --    haengt die Rechnung an einem Rezept, wird als 'zuzahlung' gebucht.
  --    mahnwesen.routes.js und statistik.routes.js filtern auf
  --    type IN ('zuzahlung','storno') und wuerden eine 'rechnung'-Zeile
  --    uebersehen — der Patient bekaeme eine Mahnung fuer bezahltes Geld.
  INSERT INTO public.belegliste
    (owner_id, type, amount_eur, patient_id, prescription_id, invoice_id,
     reference_text, zahlart, created_by)
  VALUES
    (p_owner_id,
     CASE WHEN v_rx_id IS NOT NULL THEN 'zuzahlung' ELSE 'rechnung' END,
     p_betrag_eur, v_inv.patient_id, v_rx_id, p_invoice_id,
     'Zahlungseingang Rechnung ' || COALESCE(v_inv.invoice_number, ''),
     p_zahlart, p_created_by)
  RETURNING beleg_nr INTO v_beleg_nr;

  -- 7. Rezeptvermerk. Ohne ihn zeigt die Oberflaeche das Rezept weiter als
  --    "nicht kassiert" und jemand kassiert ein zweites Mal. Entspricht dem
  --    optimistischen .is('zuzahlung_kassiert_am', null)-Claim aus
  --    kassiereZuzahlung (dashboard.js). p_zahlart direkt uebernommen statt
  --    des alten COALESCE(v_zahlart,'ueberweisung')-Fallbacks — der schrieb
  --    bei Kartenzahlung faelschlich 'ueberweisung' (Ops #271, gefunden bei
  --    der Bestandsaufnahme).
  IF v_rx_id IS NOT NULL AND v_rest = 0 THEN
    SELECT id, zuzahlung_eur, zuzahlung_befreit, zuzahlung_kassiert_am
      INTO v_rx
      FROM public.prescriptions
     WHERE id = v_rx_id
       FOR UPDATE;

    IF FOUND
       AND v_rx.zuzahlung_kassiert_am IS NULL
       AND COALESCE(v_rx.zuzahlung_befreit, false) = false
       AND COALESCE(v_rx.zuzahlung_eur, 0) > 0 THEN
      UPDATE public.prescriptions
         SET zuzahlung_kassiert_am  = now(),
             zuzahlung_kassiert_von = p_created_by,
             zuzahlung_kassiert_eur = v_rx.zuzahlung_eur,
             zuzahlung_zahlart      = p_zahlart
       WHERE id = v_rx_id;
    END IF;
  END IF;

  -- 8. Cache auf der Rechnung. NUR hier geschrieben — sonst entstehen wieder
  --    zwei Wahrheiten fuer "bezahlt".
  v_status := CASE WHEN v_rest = 0 OR v_ausbuchen THEN 'paid' ELSE 'partial' END;

  UPDATE public.invoices
     SET payment_status = v_status,
         status         = CASE WHEN v_status = 'paid' THEN 'paid' ELSE status END,
         paid_at        = CASE WHEN v_status = 'paid' THEN now() ELSE paid_at END
   WHERE id = p_invoice_id;

  RETURN jsonb_build_object(
    'zahlung_id',     v_zahlung_id,
    'ausbuchung_id',  v_ausbuchung_id,
    'beleg_nr',       v_beleg_nr,
    'payment_status', v_status,
    'offen_eur',      CASE WHEN v_ausbuchen THEN 0 ELSE v_rest END
  );
END;
$function$
;
ALTER FUNCTION public.rechnung_zahlung_buchen(p_invoice_id uuid, p_owner_id uuid, p_created_by uuid, p_betrag_eur numeric, p_zahlungsdatum date, p_gegenkonto_code text, p_gegenkonto_label text, p_restbetrag_modus text, p_ausbuchungskonto_code text, p_ausbuchungskonto_label text, p_bemerkung text, p_zahlart text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.search_diagnosen(p_q text, p_bereich text DEFAULT NULL::text, p_kind text DEFAULT 'both'::text, p_limit integer DEFAULT 25)
 RETURNS TABLE(kind text, code text, titel text, bereich text, terminal boolean, in_sector boolean, rank real)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with q as (
    select
      nullif(btrim(coalesce(p_q, '')), '')                     as raw,
      upper(replace(nullif(btrim(coalesce(p_q,'')),''), '.','')) as codeq,
      lower(nullif(btrim(coalesce(p_q,'')), ''))               as textq
  ),
  dg as (
    select
      'dg'::text                                        as kind,
      d.code,
      d.label                                           as titel,
      d.bereich,
      true                                              as terminal,
      (p_bereich is null or d.bereich = p_bereich)      as in_sector,
      (case
         when q.raw is null                                        then 50
         when upper(d.code) = q.codeq                              then 100
         when upper(replace(d.code,' ','')) like q.codeq || '%'    then 90
         when upper(d.code) like '%' || q.codeq || '%'             then 70
         when lower(d.label) like q.textq || '%'                   then 60
         else 40
       end)::real                                       as rank
    from diagnosegruppen d, q
    where d.aktiv
      and p_kind in ('dg','both')
      and (q.raw is not null or p_bereich is null or d.bereich = p_bereich)
      and (
        q.raw is null
        or upper(d.code)  like '%' || q.codeq || '%'
        or lower(d.label) like '%' || q.textq || '%'
        or lower(coalesce(d.indikation,'')) like '%' || q.textq || '%'
      )
  ),
  sect as (
    select gte, lt from icd_sector_ranges
    where p_bereich is not null and bereich = p_bereich
  ),
  icd as (
    select
      'icd'::text                                       as kind,
      i.code,
      i.titel,
      null::text                                        as bereich,
      i.terminal,
      exists (select 1 from sect s where i.code >= s.gte and i.code < s.lt) as in_sector,
      (case
         when i.code_plain = q.codeq                    then 100
         when i.code_plain like q.codeq || '%'          then 90
         when lower(i.titel) like q.textq || '%'        then 60
         when lower(i.titel) like '% ' || q.textq || '%' then 50
         else 30
       end)::real                                       as rank
    from icd10_titles i, q
    where q.raw is not null
      and p_kind in ('icd','both')
      and (
        i.code_plain like '%' || q.codeq || '%'
        or lower(i.titel) like '%' || q.textq || '%'
      )
  )
  select r.kind, r.code, r.titel, r.bereich, r.terminal, r.in_sector, r.rank
  from (select * from dg union all select * from icd) r
  order by
    r.in_sector desc,
    (r.kind = 'dg') desc,
    r.rank desc,
    r.terminal desc nulls last,
    r.code
  limit greatest(1, least(coalesce(p_limit, 25), 100));
$function$
;
ALTER FUNCTION public.search_diagnosen(p_q text, p_bereich text, p_kind text, p_limit integer) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.search_heilmittel(p_q text DEFAULT NULL::text, p_bereich text DEFAULT NULL::text, p_diagnosegruppe text DEFAULT NULL::text, p_datum date DEFAULT NULL::date, p_limit integer DEFAULT 100)
 RETURNS TABLE(code text, bereich text, label text, kuerzel text, kategorie text, preis_eur numeric, zuzahlung_eur numeric, dauer text, max_pro_tag integer, max_pro_termin integer, notiz text, rank real)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with q as (
    select
      lower(btrim(coalesce(p_q, '')))          as textq,
      upper(btrim(coalesce(p_q, '')))          as codeq,
      coalesce(p_datum, current_date)          as d
  )
  select
    h.code, h.bereich, h.label, h.kuerzel, h.kategorie,
    h.preis_eur, h.zuzahlung_eur, h.dauer,
    h.max_pro_tag, h.max_pro_termin, h.notiz,
    (case
       when q.textq = '' then 50
       when upper(h.code)    = q.codeq                     then 100
       when upper(coalesce(h.kuerzel,'')) = q.codeq        then 95
       when upper(h.code)    like q.codeq || '%'           then 90
       when upper(coalesce(h.kuerzel,'')) like q.codeq || '%' then 85
       when lower(h.label)   like q.textq || '%'           then 70
       when lower(h.label)   like '%' || q.textq || '%'    then 55
       when lower(coalesce(h.kategorie,'')) like '%' || q.textq || '%' then 40
       else 30
     end)::real as rank
  from heilmittel_katalog h, q
  where
    -- nur gültige, nicht abgelöste Positionen
    h.gueltig_ab <= q.d
    and h.gueltig_bis >= q.d
    and not h.deprecated
    and (h.ungueltig_ab is null or h.ungueltig_ab > q.d)
    and (p_bereich is null or h.bereich = p_bereich)
    and (
      p_diagnosegruppe is null
      or h.diagnosegruppen is null
      or h.diagnosegruppen @> array[p_diagnosegruppe]
    )
    and (
      q.textq = ''
      or upper(h.code) like '%' || q.codeq || '%'
      or upper(coalesce(h.kuerzel,'')) like '%' || q.codeq || '%'
      or lower(h.label) like '%' || q.textq || '%'
      or lower(coalesce(h.kategorie,'')) like '%' || q.textq || '%'
    )
  order by rank desc, h.sort, h.code
  limit greatest(1, least(coalesce(p_limit, 100), 300));
$function$
;
ALTER FUNCTION public.search_heilmittel(p_q text, p_bereich text, p_diagnosegruppe text, p_datum date, p_limit integer) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.seed_default_groups_for_business()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_mit_id UUID;
  v_sek_id UUID;
  modules_mit TEXT[] := ARRAY['dashboard','calendar','customers','services','hours','notes','anamnese','prescriptions','team'];
  modules_sek TEXT[] := ARRAY['dashboard','calendar','customers','services','hours','b2c','team'];
  m TEXT;
BEGIN
  INSERT INTO public.employee_groups (business_id, name, is_default)
  VALUES (NEW.id, 'Mitarbeiter', TRUE)
  ON CONFLICT (business_id, name) DO NOTHING
  RETURNING id INTO v_mit_id;
  IF v_mit_id IS NULL THEN
    SELECT id INTO v_mit_id FROM public.employee_groups WHERE business_id = NEW.id AND name = 'Mitarbeiter';
  END IF;
  FOREACH m IN ARRAY modules_mit LOOP
    INSERT INTO public.group_scopes (group_id, module, has_access)
    VALUES (v_mit_id, m, TRUE)
    ON CONFLICT (group_id, module) DO NOTHING;
  END LOOP;

  INSERT INTO public.employee_groups (business_id, name, is_default)
  VALUES (NEW.id, 'Sekreter', TRUE)
  ON CONFLICT (business_id, name) DO NOTHING
  RETURNING id INTO v_sek_id;
  IF v_sek_id IS NULL THEN
    SELECT id INTO v_sek_id FROM public.employee_groups WHERE business_id = NEW.id AND name = 'Sekreter';
  END IF;
  FOREACH m IN ARRAY modules_sek LOOP
    INSERT INTO public.group_scopes (group_id, module, has_access)
    VALUES (v_sek_id, m, TRUE)
    ON CONFLICT (group_id, module) DO NOTHING;
  END LOOP;

  RETURN NEW;
END $function$
;
ALTER FUNCTION public.seed_default_groups_for_business() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.set_bookings_business_id_default()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner UUID;
  v_resolved UUID;
BEGIN
  IF NEW.business_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  v_owner := COALESCE(NEW.owner_id, auth.uid());
  IF v_owner IS NULL THEN RETURN NEW; END IF;

  -- 1) Önce: employee'nin owner'in default business'inde atamasi varsa onu kullan
  IF NEW.user_id IS NOT NULL THEN
    SELECT eba.business_id INTO v_resolved
      FROM public.employee_business_assignments eba
      JOIN public.businesses b ON b.id = eba.business_id
     WHERE eba.employee_id = NEW.user_id
       AND b.owner_id = v_owner
       AND b.is_default
     LIMIT 1;
  END IF;

  -- 2) Default'a atanmamissa employee'nin owner altindaki herhangi bir atamasini kullan
  IF v_resolved IS NULL AND NEW.user_id IS NOT NULL THEN
    SELECT eba.business_id INTO v_resolved
      FROM public.employee_business_assignments eba
      JOIN public.businesses b ON b.id = eba.business_id
     WHERE eba.employee_id = NEW.user_id
       AND b.owner_id = v_owner
     ORDER BY b.is_default DESC, b.created_at ASC
     LIMIT 1;
  END IF;

  -- 3) Son care: owner'in default business'i
  IF v_resolved IS NULL THEN
    SELECT id INTO v_resolved
      FROM public.businesses
     WHERE owner_id = v_owner AND is_default
     LIMIT 1;
  END IF;

  NEW.business_id := v_resolved;
  RETURN NEW;
END $function$
;
ALTER FUNCTION public.set_bookings_business_id_default() OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.set_business_id_default()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner UUID;
BEGIN
  IF NEW.business_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- 1) owner_id kolonu varsa onu kullan
  BEGIN
    EXECUTE format('SELECT ($1).owner_id') INTO v_owner USING NEW;
  EXCEPTION WHEN OTHERS THEN
    v_owner := NULL;
  END;

  -- 2) yoksa auth.uid()
  IF v_owner IS NULL THEN
    v_owner := auth.uid();
  END IF;

  IF v_owner IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT b.id INTO NEW.business_id
    FROM public.businesses b
    JOIN public.profiles p ON p.id = v_owner
   WHERE b.owner_id = COALESCE(p.owner_id, p.id)
     AND b.is_default
   LIMIT 1;

  RETURN NEW;
END $function$
;
ALTER FUNCTION public.set_business_id_default() OWNER TO postgres;
COMMENT ON FUNCTION public.set_business_id_default() IS 'BEFORE INSERT trigger: if business_id is NULL, auto-resolve from owner_id or auth.uid() via get_default_business logic';

CREATE OR REPLACE FUNCTION public.set_gmail_token(p_user_id uuid, p_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
BEGIN
  -- Remove existing secret for this user if present
  DELETE FROM vault.secrets WHERE name = 'gmail_token:' || p_user_id::text;
  -- Store new token
  PERFORM vault.create_secret(p_token, 'gmail_token:' || p_user_id::text, 'Gmail refresh token for user ' || p_user_id::text);
END;
$function$
;
ALTER FUNCTION public.set_gmail_token(p_user_id uuid, p_token text) OWNER TO postgres;

CREATE OR REPLACE FUNCTION public.set_invoice_nummer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_jahr int; v_nr bigint;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.rechnung_nr IS NULL THEN
      v_jahr := COALESCE(EXTRACT(YEAR FROM NEW.issued_at)::int, EXTRACT(YEAR FROM now())::int);
      v_nr   := naechste_nummer(NEW.owner_id, 'rechnung', v_jahr);
      NEW.rechnung_nr    := v_nr;
      NEW.invoice_number := 'INV-' || v_jahr || '-' || lpad(v_nr::text, 4, '0');
    END IF;
    RETURN NEW;
  END IF;

  -- § 14 Abs. 4 Nr. 4 UStG: einmal vergeben, nie wieder geaendert.
  -- COALESCE statt harter Zuweisung: war noch keine Nummer da (Altbestand),
  -- darf genau einmal eine gesetzt werden.
  NEW.rechnung_nr    := COALESCE(OLD.rechnung_nr, NEW.rechnung_nr);
  NEW.invoice_number := COALESCE(OLD.invoice_number, NEW.invoice_number);
  RETURN NEW;
END;
$function$
;
ALTER FUNCTION public.set_invoice_nummer() OWNER TO postgres;

